reference_cypher:
MATCH p=(a:Museum {museum_id: "M0402"})-[:LOCATED_IN]->(sg1:Sigungu)-[:PART_OF]->(s:Sido)<-[:PART_OF]-(sg2:Sigungu)<-[:LOCATED_IN]-(b:Museum {museum_id: "M0448"})
WHERE sg1 <> sg2
RETURN a.museum_id AS anchor_id, a.name AS anchor_name, a.sigungu AS anchor_sigungu, s.name AS common_sido, b.museum_id AS museum_id, b.name AS name, b.sigungu AS target_sigungu, p;

MATCH p=(m:Museum {museum_id: "M0710"})-[:HAS_SPAN]->(seed:TextSpan)-[:SUPPORTED_BY]->(d:SourceDocument)<-[:SUPPORTED_BY]-(other:TextSpan)
WHERE seed.text CONTAINS "예술의 뜰" AND other <> seed AND EXISTS { MATCH (m)-[:HAS_SPAN]->(other) }
RETURN d.doc_id AS doc_id, d.source_locator AS source_locator, seed.text AS seed_text, other.span_id AS other_span_id, other.start AS other_start, other.end AS other_end, other.text AS other_text, p
ORDER BY other_start, doc_id;
